    canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const g=canvas.getContext('2d');g.scale(ratio,ratio);
    const style=getComputedStyle(canvas),color=k=>style.getPropertyValue(k).trim(),palette=[1,2,3,4,5,6].map(i=>color('--temperature-'+i));
