  function drawContour(g,mesh,values,level,X,Y){
    // Join exact P1 mesh-edge crossings. Round only the display path within 5 px;
    // nodal temperatures, extrema, the raster interpolant and samples stay unchanged.
    const nodes=new Map(),edges=[];
    for(const tri of mesh.triangles){const ends=[];for(let j=0;j<3;j++){const a=tri[j],b=tri[(j+1)%3],va=values[a],vb=values[b];if((va<level&&vb>=level)||(vb<level&&va>=level)){const t=(level-va)/(vb-va),key=t<1e-12?'v'+a:t>1-1e-12?'v'+b:Math.min(a,b)+':'+Math.max(a,b);if(!nodes.has(key))nodes.set(key,{point:[X(mesh.points[a][0]+t*(mesh.points[b][0]-mesh.points[a][0])),Y(mesh.points[a][1]+t*(mesh.points[b][1]-mesh.points[a][1]))],edges:[]});ends.push(key);}}if(ends.length===2&&ends[0]!==ends[1]){const i=edges.length;edges.push(ends);ends.forEach(k=>nodes.get(k).edges.push(i));}}
    const used=new Set(),trace=start=>{const points=[nodes.get(start).point];let key=start;while(true){const edge=nodes.get(key).edges.find(i=>!used.has(i));if(edge==null)break;used.add(edge);key=edges[edge].find(k=>k!==key);points.push(nodes.get(key).point);if(key===start)break;}if(points.length<2)return;g.moveTo(...points[0]);for(let i=1;i<points.length-1;i++){const a=points[i-1],b=points[i],c=points[i+1],u=Math.hypot(b[0]-a[0],b[1]-a[1]),v=Math.hypot(c[0]-b[0],c[1]-b[1]),r=Math.min(5,u/3,v/3);if(u===0||v===0){g.lineTo(...b);continue;}g.lineTo(b[0]+(a[0]-b[0])*r/u,b[1]+(a[1]-b[1])*r/u);g.quadraticCurveTo(...b,b[0]+(c[0]-b[0])*r/v,b[1]+(c[1]-b[1])*r/v);}g.lineTo(...points.at(-1));};
    g.beginPath();for(const [key,node]of nodes)if(node.edges.length===1)trace(key);for(const [key]of nodes)trace(key);g.stroke();
  }
